import {animals} from './catalog.js';
export const WORLD=1000,MAX_PLAYERS=8;
export const THEMES=['Kota Maple','Pasar Malam Lentera','Taman Kota Alder','Perumahan Willow','Pertokoan Magnolia','Perkebunan Clover'];
export const ITEMS=[{id:'bike',icon:'🚲',name:'Sepeda',price:180,description:'Kecepatan berjalan ×1,6.',speed:1.6},{id:'board',icon:'🛹',name:'Skateboard',price:120,description:'Kecepatan berjalan ×1,3.',speed:1.3},{id:'cutter',icon:'✂️',name:'Pemotong gembok',price:200,description:'Buka kandang dalam 3 detik.'},{id:'torch',icon:'🔥',name:'Las mini',price:240,description:'Buka kandang dalam 6 detik.'},{id:'jet',icon:'🚀',name:'Jetpack',price:600,description:'Terbang rendah dengan kecepatan ×2,5.',speed:2.5},{id:'infra',icon:'🥽',name:'Kacamata infrared',price:300,description:'Sorot hewan hingga jarak 200 unit.'},{id:'digital',icon:'🗺️',name:'Digital map',price:220,description:'Lacak posisi hewan di City Map.'},{id:'hound',icon:'🐕‍🦺',name:'Anjing pelacak',price:350,description:'Buka jejak terbaru setiap hewan berpindah.'},{id:'whistle',icon:'📯',name:'Peluit penenang',price:160,description:'Hewan berhenti bergerak selama 20 detik.'}];
export function rng(seed){let a=seed>>>0;return()=>{a+=0x6d2b79f5;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}
export const distance=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z);
export function makePlan(level,seed){let r=rng(seed+level*971),theme=(level-1)%6,river=300-(level%3)*100,blocks=[];for(let x=-400;x<=400;x+=100)for(let z=-400;z<=400;z+=100){if(Math.abs(x-river)<58)continue;let kind=Math.abs(x)<125&&Math.abs(z)<125?'park':r()<.32?'homes':r()<.5?'shops':'office';if(theme===1&&z>50)kind='market';if(theme===2&&r()<.62)kind='park';if(theme===3&&r()<.7)kind='homes';if(theme===4&&r()<.65)kind='shops';if(theme===5&&r()<.67)kind='farm';blocks.push({x,z,kind})}return{theme,river,blocks}}
export function mission(level,seed){let r=rng(seed+level*113),plan=makePlan(level,seed),parks=plan.blocks.filter(b=>b.kind==='park'),homes=plan.blocks.filter(b=>b.kind==='homes');let park=parks[Math.floor(r()*parks.length)]||{x:0,z:0},home=homes[Math.floor(r()*homes.length)]||{x:-400,z:400};let order=Array.from({length:animals.length},(_,i)=>i),shuffle=rng(seed);for(let i=order.length-1;i>0;i--){let j=Math.floor(shuffle()*(i+1));[order[i],order[j]]=[order[j],order[i]]}let species=order[(level-1)%animals.length];let route=Array.from({length:7},()=>({x:park.x-28+r()*56,z:park.z-28+r()*56}));return{level,seed,theme:plan.theme,animal:species,owner:['Kak Sarah','Pak Bima','Bu Rani','Kak Dito','Bu Maya'][level%5],ownerPos:{x:home.x+39,z:home.z+39},truck:{x:plan.river-50,z:450},route,reward:Math.round((140+species*6+level*8)*(0.8+r()*.6)),duration:Math.max(420,900-level*8),moveEvery:Math.max(12,32-Math.floor(level/3))}}
export class GameEngine{
 constructor(level=1,seed=Math.floor(Math.random()*1e8),now=Date.now()){this.players={};this.events=[];this.counter=0;this.level=level;this.seed=seed;this.reset(level,now)}
 reset(level,now){this.level=level;this.m=mission(level,this.seed);this.phase='ready';this.deadline=0;this.started=0;this.carrier=null;this.pet={...this.m.route[0]};this.routeIndex=0;this.lastMove=now;this.freezeUntil=0;this.payout=null;this.clues=1;for(let p of Object.values(this.players)){p.carrying=false;p.releaseAt=0;p.cooldown=0;p.balance=p.balance??250;p.clues=1;p.lastSeen=null;p.target=null}this.emit('level',`Level ${level}: ${THEMES[this.m.theme]}`)}
 emit(type,text){this.events.push({id:++this.counter,type,text});this.events=this.events.slice(-12)}
 add(id,name='Penjelajah',now=Date.now()){if(this.players[id])return{ok:true};if(Object.keys(this.players).length>=MAX_PLAYERS)return{ok:false,error:'Ruang penuh: maksimal 8 pemain.'};let r=rng(this.seed+Object.keys(this.players).length*777+this.counter),roads=[-450,-350,-250,-150,-50,50,150,250,350,450];let x=roads[Math.floor(r()*roads.length)],z=roads[Math.floor(r()*roads.length)];if(Math.abs(x-this.m.truck.x-50)<40)x=-450;this.players[id]={id,name:String(name).slice(0,22).replace(/[<>]/g,''),x,z,color:Object.keys(this.players).length,mode:'team',balance:250,inventory:[],clues:1,cooldown:0,releaseAt:0,lastPose:now};this.emit('join',`${this.players[id].name} tiba di kota.`);return{ok:true}}
 remove(id){let p=this.players[id];if(!p)return;if(this.carrier===id){this.carrier=null;this.phase=this.deadline>Date.now()?'search':'captured';this.pet={x:p.x,z:p.z}}delete this.players[id];this.emit('leave',`${p.name} meninggalkan kota.`)}
 speed(p){return 6.5*Math.max(1,...ITEMS.filter(i=>p.inventory.includes(i.id)).map(i=>i.speed||1))}
 pose(id,position,now){let p=this.players[id];if(!p||!Number.isFinite(position.x)||!Number.isFinite(position.z))return;let elapsed=Math.min(1.5,Math.max(0,(now-p.lastPose)/1000));let max=this.speed(p)*1.5*elapsed+4;let dx=position.x-p.x,dz=position.z-p.z,len=Math.hypot(dx,dz),factor=Math.min(1,max/(len||1));p.x=Math.max(-488,Math.min(488,p.x+dx*factor));p.z=Math.max(-488,Math.min(488,p.z+dz*factor));p.lastPose=now}
 act(id,action,now=Date.now()){let p=this.players[id];if(!p)return{ok:false,error:'Pemain belum bergabung.'};let fail=error=>({ok:false,error});if(!action||typeof action.type!=='string')return fail('Aksi tidak valid.');let type=action.type;
 if(type==='buy'){let item=ITEMS.find(i=>i.id===action.item);if(!item||p.inventory.includes(item.id)||p.balance<item.price)return fail('Koin kurang atau alat sudah dimiliki.');p.balance-=item.price;p.inventory.push(item.id);return{ok:true}}
 if(type==='mode'){p.mode=p.mode==='team'?'rival':'team';this.emit('mode',`${p.name} memilih ${p.mode==='team'?'kolaborasi':'kompetisi'}.`);return{ok:true}}
 if(type==='start'){if(this.phase!=='ready')return fail('Misi sudah berjalan.');this.phase='search';this.started=now;this.deadline=now+this.m.duration*1000;this.lastMove=now;this.emit('start','Misi dimulai. Cari jejak, lalu jemput hewan!');return{ok:true}}
 if(type==='clue'){if(!['search','carrying','captured'].includes(this.phase))return fail('Mulai misi terlebih dahulu.');p.clues=Math.min(3,p.clues+1);p.lastSeen={...this.pet,at:now};if(p.mode==='team')for(let member of Object.values(this.players))if(member.mode==='team'){member.clues=Math.max(member.clues,p.clues);member.lastSeen={...p.lastSeen}}this.clues=Math.max(this.clues,p.clues);return{ok:true}}
 if(type==='whistle'){if(!p.inventory.includes('whistle'))return fail('Beli peluit di toko.');if(p.cooldown>now)return fail('Tunggu alat siap digunakan kembali.');this.freezeUntil=now+20000;p.cooldown=now+30000;this.emit('whistle',`${p.name} menenangkan hewan selama 20 detik.`);return{ok:true}}
 if(type==='claim'){if(this.phase!=='search')return fail('Hewan tidak sedang bebas di kota.');if(distance(p,this.pet)>15)return fail('Dekati hewan hingga jarak 15 unit.');this.phase='carrying';this.carrier=id;this.emit('found',`${p.name} menemukan hewan! Antar ke pemilik.`);return{ok:true}}
 if(type==='steal'){if(this.phase!=='carrying'||this.carrier===id)return fail('Tidak ada hewan untuk direbut.');if(p.cooldown>now)return fail('Tunggu 12 detik sebelum merebut lagi.');let c=this.players[this.carrier];if(!c||distance(p,c)>15)return fail('Dekati pembawa hewan hingga 15 unit.');p.mode='rival';p.cooldown=now+12000;c.cooldown=now+12000;this.carrier=id;this.emit('betray',`${p.name} merebut hewan! Hadiah menjadi milik pengantar.`);return{ok:true}}
 if(type==='release'){if(this.phase!=='captured')return fail('Kandang tidak sedang berisi hewan.');if(distance(p,this.m.truck)>22)return fail('Dekati truk hingga jarak 22 unit.');let tool=action.tool||'hook';if(tool!=='hook'&&!p.inventory.includes(tool))return fail('Alat belum dimiliki.');let seconds=tool==='cutter'?3:tool==='torch'?6:18;p.releaseTool=tool;p.releaseAt=now+seconds*1000;p.releaseOrigin={x:p.x,z:p.z};this.emit('rescue',`${p.name} membuka kandang (${seconds} detik). Tetap dekat truk.`);return{ok:true}}
 if(type==='deliver'){if(this.phase!=='carrying'||this.carrier!==id)return fail('Kamu belum membawa hewan.');if(distance(p,this.m.ownerPos)>22)return fail('Dekati pemilik hingga jarak 22 unit.');this.phase='won';let team=p.mode==='team'?Object.values(this.players).filter(x=>x.mode==='team'):[p];let amount=Math.floor(this.m.reward/team.length);this.payout={};for(let member of team){let gain=amount+(member.id===id?this.m.reward-amount*team.length:0);member.balance+=gain;this.payout[member.id]=gain}this.emit('won',`${p.name} mengantar hewan pulang! ${this.m.reward} koin dibagikan kepada ${team.length} pemain.`);return{ok:true}}
 return fail('Aksi tidak dikenal.')}
 tick(now=Date.now()){if(this.phase==='search'&&now>=this.deadline){this.phase='captured';this.carrier=null;this.pet={...this.m.truck};this.deadline=now+95000;this.emit('captured','Polisi satwa membawa hewan ke truk. Selamatkan sebelum patroli kembali!')}
 else if(this.phase==='carrying'&&now>=this.deadline){this.phase='lost';this.emit('lost','Patroli menangkap pembawa hewan. Misi gagal.')}
 else if(this.phase==='captured'&&now>=this.deadline){this.phase='lost';this.emit('lost','Patroli kembali. Waktu penyelamatan habis.')}
 if(this.phase==='search'&&now>=this.freezeUntil){let next=this.m.route[(this.routeIndex+1)%this.m.route.length];if(now-this.lastMove>=this.m.moveEvery*1000){let len=distance(this.pet,next),step=2.8*.1;if(len<1){this.routeIndex=(this.routeIndex+1)%this.m.route.length;this.lastMove=now;this.emit('move','Hewan berpindah lokasi. Perbarui jejak terakhirmu.')}else{this.pet.x+=(next.x-this.pet.x)/len*step;this.pet.z+=(next.z-this.pet.z)/len*step}}}
 if(this.phase==='carrying'&&this.players[this.carrier])this.pet={x:this.players[this.carrier].x+3,z:this.players[this.carrier].z};
 for(let p of Object.values(this.players)){if(p.inventory.includes('hound')){p.clues=3;p.lastSeen={...this.pet,at:now}}if(p.releaseAt&&this.phase==='captured'){if(distance(p,this.m.truck)>24){p.releaseAt=0;this.emit('cancel','Pembukaan kandang batal: pemain menjauh dari truk.')}else if(now>=p.releaseAt){this.carrier=p.id;this.phase='carrying';this.deadline=now+120000;p.releaseAt=0;this.emit('rescued',`${p.name} membebaskan hewan! Antar ke pemilik sebelum patroli menangkapmu.`);for(let q of Object.values(this.players))q.releaseAt=0}}}}
 snapshot(now=Date.now()){return{version:2,m:this.m,players:this.players,phase:this.phase,deadline:this.deadline,started:this.started,now,pet:this.pet,carrier:this.carrier,clues:this.clues,payout:this.payout,events:this.events,freezeUntil:this.freezeUntil}}
}
